<script setup lang="ts">
import {ref,onMounted,nextTick,computed} from 'vue'
import Icon from '../components/Icon.vue'
import {state,t,fmt,api,wp,notify} from '../state'
const messages=ref<any[]>([]),question=ref(''),busy=ref(false),bottom=ref<HTMLElement>()
onMounted(async()=>{try{messages.value=await api(wp('/assistant'))}catch(e:any){notify(e.message,true)}})
const prompts=computed(()=>[t('Which risks deserve our attention this week?','Какие риски требуют нашего внимания на этой неделе?'),t('How do these developments affect our current priorities?','Как события связаны с нашими рисками финансирования?'),t('What should we validate before acting on these opportunities?','Что проверить до реализации этих возможностей?')])
async function ask(prompt?:string){if(prompt)question.value=prompt;if(question.value.trim().length<4||busy.value)return;const q=question.value;question.value='';busy.value=true;try{const r=await api(wp('/assistant'),{method:'POST',body:{question:q,locale:state.locale}});messages.value.push(r);await nextTick();bottom.value?.scrollIntoView({behavior:'smooth'})}catch(e:any){question.value=q;notify(e.message,true)}finally{busy.value=false}}
function open(id:string){state.selectedEvent=state.events.find(e=>e.id===id)}
</script>
<template><div class="page-heading"><div><span class="eyebrow">{{t('GO BEYOND THE HEADLINE','ЗАГЛЯНИТЕ ГЛУБЖЕ ЗАГОЛОВКА')}}</span><h1>{{t('A question worth asking.','Вопрос, который стоит задать.')}}</h1><p>{{t('Explore your company’s signals with an assistant grounded in your workspace evidence.','Изучайте сигналы компании с помощником, который опирается на материалы вашего пространства.')}}</p></div><span class="badge neutral"><Icon name="ShieldCheck" :size="14"/>{{t('Workspace evidence only','Только материалы пространства')}}</span></div><div class="assistant-layout"><section class="card conversation"><div v-if="!messages.length" class="assistant-welcome"><span class="assistant-orb"><Icon name="Sparkles" :size="32"/></span><h2>{{t('Let’s connect the dots.','Найдём связи между событиями.')}}</h2><p>{{t('Ask about an event, compare business impacts or explore what your team should check next. When the evidence is incomplete, I’ll say so.','Спросите о событии, сравните влияние на бизнес или уточните следующий шаг. Если данных недостаточно, я об этом скажу.')}}</p><button v-for="p in prompts" :key="p" class="prompt-button" @click="ask(p)">{{p}}<Icon name="ArrowUpRight" :size="16"/></button></div><div v-for="m in messages" :key="m.id" class="conversation-pair"><div class="user-question"><span class="avatar">{{state.user.name.slice(0,1)}}</span><p>{{m.question}}</p></div><div class="assistant-response"><span class="spark-icon"><Icon name="Sparkles" :size="20"/></span><div><span class="tiny muted">SIGNALDESK · {{fmt(m.created_at,{hour:'2-digit',minute:'2-digit'})}}</span><p class="answer-text">{{m.answer}}</p><div class="brief-citations"><button v-for="(id,i) in m.event_ids" :key="id" @click="open(id)"><Icon name="Link2" :size="13"/>{{t('Evidence','Основание')}} {{Number(i)+1}}<Icon name="ArrowUpRight" :size="12"/></button><RouterLink v-if="m.bank_ids?.length" to="/sources?tab=research" class="text-link small">{{t('Referenced bank research','Обзоры банка')}}<Icon name="BookOpen" :size="13"/></RouterLink></div><button v-if="m.follow_up" class="follow-up" @click="ask(m.follow_up)" :disabled="busy"><Icon name="CornerDownRight" :size="15"/>{{m.follow_up}}</button></div></div></div><div v-if="busy" class="assistant-thinking" role="status"><Icon name="LoaderCircle" class="spin" :size="18"/><span>{{t('Checking your company context and supporting evidence…','Проверяем контекст компании и источники…')}}</span></div><div ref="bottom"></div><form @submit.prevent="ask()" class="assistant-composer"><label for="assistant-input" class="sr-only">{{t('Ask SignalDesk','Спросить SignalDesk')}}</label><textarea id="assistant-input" v-model="question" rows="2" :placeholder="t('What does this mean for our business?','Что это означает для нашего бизнеса?')" maxlength="1500" @keydown.enter.exact.prevent="ask()"></textarea><div class="row between"><span class="small muted">{{t('Grounded in sources. Open about uncertainty.','На основе источников. С учётом неопределённости.')}}</span><button class="btn primary" :disabled="busy||question.trim().length<4"><Icon name="ArrowUp" :size="18"/>{{t('Ask','Спросить')}}</button></div></form></section><aside><section class="card"><span class="form-section-icon"><Icon name="Building2" :size="21"/></span><h3>{{t('Your context is the starting point','Начинаем с вашего контекста')}}</h3><p class="muted small">{{state.workspace.name}} · {{state.workspace.profile.industry}}</p><div class="form-divider"></div><h4>{{t('Confirmed exposures','Указанные факторы')}}</h4><div class="context-item" v-for="e in state.workspace.profile.exposures" :key="e"><span class="live-dot"></span>{{e}}</div><RouterLink to="/company" class="text-link mt-lg">{{t('Review company context','Проверить контекст')}}<Icon name="ArrowRight" :size="14"/></RouterLink></section><div class="notice mt-lg"><Icon name="Info" :size="19"/><p>{{t('Answers support your decisions. They do not replace verification of contracts, current regulation or financial data.','Ответы помогают принимать решения. Они не заменяют проверку договоров, актуальных норм и финансовых данных.')}}</p></div></aside></div></template>
